with tempfile.TemporaryDirectory(prefix='umusic-ui-daily-') as directory:
 work=pathlib.Path(directory)
 for name,text in files.items():
  p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 for name in ['UiFeatures','DailySign']:
  p=work/f'com/xiandehuang/umusic/{name}.java';p.write_text((ROOT/f'app/src/main/java/com/xiandehuang/umusic/{name}.java').read_text())
 out=work/'classes';out.mkdir()
 proc=subprocess.run(['javac','-encoding','UTF-8','-d',str(out)]+[str(p) for p in work.rglob('*.java')],capture_output=True,text=True)
 if proc.returncode:print(proc.stderr);raise SystemExit(proc.returncode)
 subprocess.run(['java','-cp',str(out),'com.xiandehuang.umusic.UiDailyTest'],check=True)
